using System.Text.Json;
using SefaXTV.WindowsLab;
int n=0;
void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);n++;}
var g=new ProbeGate();var a=new object();var b=new object();var t=new string('a',32);var t2=new string('b',32);
string Url(int seq,string token,string mode="play")=>$"{ProbeGate.Fixture}#seq={seq}&token={token}&mode={mode}";
JsonElement Msg(int seq=1,string? token=null,string? url=null,int counter=1,double media=1,double delta=.25,int frames=0,string method="time",string type="video:advanced")=>JsonSerializer.SerializeToElement(new {protocol=ProbeGate.Protocol,type,seq,token=token??t,url=url??Url(seq,token??t),counter,mediaTime=media,delta,frameDelta=frames,method});
Check(!g.Start(1,t,Url(1,t)),"not ready");g.SetReady(true);
Check(!g.Start(1,"bad",Url(1,"bad")),"token shape");Check(!g.Start(1,t,"https://example.invalid/"),"foreign URL");Check(!g.Start(1,t,Url(1,t,"fail")),"mode restriction");Check(g.Start(1,t,Url(1,t)),"start");Check(!g.Proof(a,Url(1,t),Msg()),"unbound frame");Check(!g.Bind(a,Url(2,t)),"wrong navigation");Check(g.Bind(a,Url(1,t)),"bind actual frame");Check(!g.Bind(b,Url(1,t)),"duplicate frame");Check(!g.Proof(b,Url(1,t),Msg()),"wrong frame");Check(!g.Proof(a,Url(2,t),Msg()),"wrong actual URL");Check(!g.Proof(a,Url(1,t),Msg(seq:2)),"wrong sequence");Check(!g.Proof(a,Url(1,t),Msg(token:t2)),"wrong token");Check(!g.Proof(a,Url(1,t),Msg(url:Url(2,t))),"wrong claimed URL");Check(!g.Proof(a,Url(1,t),Msg(type:"loaded")),"load not proof");Check(!g.Proof(a,Url(1,t),Msg(delta:.1)),"time threshold");Check(!g.Proof(a,Url(1,t),Msg(frames:1)),"time frame mismatch");Check(!g.Proof(a,Url(1,t),Msg(method:"frames",frames:0)),"frame count");Check(g.Proof(a,Url(1,t),Msg()),"valid time");Check(!g.Proof(a,Url(1,t),Msg()),"replay");Check(g.Proof(a,Url(1,t),Msg(counter:2,media:1.5,delta:.2,frames:2,method:"frames")),"frame heartbeat");Check(!g.Proof(a,Url(1,t),Msg(counter:3,media:1.2)),"time rollback");g.InvalidateFrame(b);Check(g.IsBound(a),"unrelated destruction");g.InvalidateFrame(a);Check(!g.Proof(a,Url(1,t),Msg(counter:3,media:2)),"navigation invalidation");Check(!g.Start(1,t,Url(1,t)),"sequence reuse");Check(g.Start(2,t2,Url(2,t2)),"new attempt");Check(g.Bind(b,Url(2,t2)),"new frame");Check(!g.Stop(1,t),"stale stop");Check(!g.Proof(a,Url(2,t2),Msg(2,t2)),"old frame");Check(g.Proof(b,Url(2,t2),Msg(2,t2)),"backup proof");g.SetReady(false);Check(!g.Proof(b,Url(2,t2),Msg(2,t2,counter:2,media:2)),"minimized");g.SetReady(true);Check(!g.Start(2,t2,Url(2,t2)),"resume requires fresh sequence");g.NewDocument();g.SetReady(true);Check(g.Start(1,t,Url(1,t)),"new document");
Check(ProbeGate.ResourceAllowed(ProbeGate.App,"GET"),"local app");Check(ProbeGate.ResourceAllowed("https://sedathut-sys.github.io/sefaxtv/catalog/v4.json","GET"),"catalog HTTPS");Check(!ProbeGate.ResourceAllowed("https://sedathut-sys.github.io/sefaxtv/index.html","GET"),"remote HTML rejected");Check(!ProbeGate.ResourceAllowed("https://example.invalid/video","GET"),"foreign resource");Check(!ProbeGate.ResourceAllowed(ProbeGate.App,"POST"),"non GET");Check(!ProbeGate.ResourceAllowed(ProbeGate.App+"?x=1","GET"),"query rejected");Console.WriteLine($"TOTAL {n}");
